import { alreadyRefunded, insufficientAmount, missingResource, type AppError } from '../kernel/errors.js';
import { err, ok, type Result } from '../kernel/result.js';
import { lookupOrder, markOrderAsRefunded } from './order.service.js';

export function refundOrder(orderId: string): Result<{ refunded: true }, AppError> {
  const order = lookupOrder(orderId);

  if (order === undefined) {
    return err(missingResource(`order ${orderId}`));
  }

  if (order.refunded) {
    return err(alreadyRefunded(orderId));
  }

  if (order.total < 10) {
    return err(insufficientAmount(orderId, order.total));
  }

  markOrderAsRefunded(orderId);
  return ok({ refunded: true });
}

